-- committed balance is 100

-- T1
BEGIN;
UPDATE accounts SET balance = 50 WHERE id = 1;   -- no COMMIT yet

-- T2, on a level that allows dirty reads
BEGIN;
SELECT balance FROM accounts WHERE id = 1;

-- committed balance is 100

-- T1
BEGIN;
UPDATE accounts SET balance = 50 WHERE id = 1;

-- T2, dirty reads allowed
BEGIN;
SELECT balance FROM accounts WHERE id = 1;   -- reads 50 and approves a payout
COMMIT;

-- T1
ROLLBACK;

-- T1 (only committed data is visible, no snapshot is taken)
BEGIN;
SELECT balance FROM accounts WHERE id = 1;   -- returns 100

-- T2
BEGIN;
UPDATE accounts SET balance = 120 WHERE id = 1;
COMMIT;

-- T1, same transaction, repeats its own query
SELECT balance FROM accounts WHERE id = 1;

-- T1 (only committed data is visible, no snapshot is taken)
BEGIN;
SELECT count(*) FROM orders WHERE status = 'PENDING';   -- returns 3

-- T2
BEGIN;
INSERT INTO orders (id, status) VALUES (99, 'PENDING');
COMMIT;

-- T1, same transaction, repeats its own query
SELECT count(*) FROM orders WHERE status = 'PENDING';

-- stored stock is 10; each transaction sells one item

-- T1
BEGIN;
SELECT stock FROM products WHERE id = 1;   -- reads 10

-- T2
BEGIN;
SELECT stock FROM products WHERE id = 1;   -- reads 10

-- T1 computes 10 - 1
UPDATE products SET stock = 9 WHERE id = 1;
COMMIT;

-- T2 computes 10 - 1 from its own read
UPDATE products SET stock = 9 WHERE id = 1;
COMMIT;

-- T1 works from a stable snapshot taken at its start
BEGIN;
SELECT balance FROM accounts WHERE id = 1;   -- returns 100

-- T2
BEGIN;
UPDATE accounts SET balance = 120 WHERE id = 1;
COMMIT;

-- T1, same transaction
SELECT balance FROM accounts WHERE id = 1;

-- PostgreSQL. The committed balance is 100.
-- Another open transaction has written 50 without committing.
BEGIN TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT balance FROM accounts WHERE id = 1;

-- Goal: sell one item. Two clients run this at the same time.
BEGIN;
SELECT stock FROM products WHERE id = 1;   -- the application reads 10
UPDATE products SET stock = 9 WHERE id = 1;
COMMIT;

-- PostgreSQL default isolation level. Stored stock is 10.

-- T1
BEGIN;
SELECT stock FROM products WHERE id = 1;   -- returns 10

-- T2
BEGIN;
UPDATE products SET stock = 7 WHERE id = 1;
COMMIT;

-- T1, same transaction
SELECT stock FROM products WHERE id = 1;      -- (a)
UPDATE products SET stock = 9 WHERE id = 1;   -- 10 - 1, from T1's first read
COMMIT;

practice.code:
-- Stored stock is 10. PostgreSQL default isolation level.

-- T1
BEGIN;
UPDATE products SET stock = stock - 1 WHERE id = 1;

-- T2
BEGIN;
UPDATE products SET stock = stock - 1 WHERE id = 1;   -- waits for T1

-- T1
COMMIT;
-- T2
COMMIT;

-- Optimistic locking attempt. The row was read with version = 3.
BEGIN;
UPDATE products SET stock = 9, version = 4 WHERE id = 1;
COMMIT;
